Task: Add a paginate(items, page, pageSize) helper for list endpoints.

Acceptance criteria:
- Pages are 1-indexed: page 1 returns the first pageSize items
- pageSize defaults to 20 when omitted
- page values below 1 throw a RangeError
- The result includes totalPages, rounded up

Diff:
--- /dev/null
+++ b/src/paginate.ts
@@ -0,0 +1,14 @@
+export interface Page<T> {
+  items: T[];
+  page: number;
+  totalPages: number;
+}
+
+export function paginate<T>(items: T[], page: number, pageSize = 10): Page<T> {
+  if (page < 1) {
+    throw new RangeError(`page must be >= 1, got ${page}`);
+  }
+  const start = (page - 1) * pageSize;
+  const totalPages = Math.ceil(items.length / pageSize);
+  return { items: items.slice(start, start + pageSize), page, totalPages };
+}
--- /dev/null
+++ b/src/paginate.test.ts
@@ -0,0 +1,11 @@
+import { paginate } from "./paginate";
+
+test("returns the requested page", () => {
+  const items = Array.from({ length: 45 }, (_, i) => i);
+  expect(paginate(items, 2, 20).items[0]).toBe(20);
+  expect(paginate(items, 3, 20).totalPages).toBe(3);
+});
+
+test("rejects page 0", () => {
+  expect(() => paginate([1, 2, 3], 0)).toThrow(RangeError);
+});

