Task: Add validatePassword(pw) that returns a list of human-readable rule violations for the signup form.

Acceptance criteria:
- Passwords of 12 or more characters pass the length rule
- A password without a digit produces the error "must contain a digit"
- A password without an uppercase letter produces an error
- All failing rules are reported, not just the first

Diff:
--- /dev/null
+++ b/src/auth/password.ts
@@ -0,0 +1,15 @@
+export const MIN_PASSWORD_LENGTH = 12;
+
+export function validatePassword(pw: string): string[] {
+  const errors: string[] = [];
+  if (pw.length <= MIN_PASSWORD_LENGTH) {
+    errors.push(`must be at least ${MIN_PASSWORD_LENGTH} characters`);
+  }
+  if (!/[0-9]/.test(pw)) {
+    errors.push("must contain a digit");
+  }
+  if (!/[A-Z]/.test(pw)) {
+    errors.push("must contain an uppercase letter");
+  }
+  return errors;
+}

