Task: Make the debounce utility cancelable so components can drop pending calls on unmount.

Acceptance criteria:
- The returned function exposes a cancel() method
- Calling cancel() prevents a pending invocation from running
- Calls within `wait` ms still collapse into one trailing call with the latest arguments
- A test covers cancel()

Diff:
--- a/src/util/debounce.ts
+++ b/src/util/debounce.ts
@@ -1,12 +1,24 @@
-export function debounce<A extends unknown[]>(fn: (...args: A) => void, wait: number) {
-  let t: ReturnType<typeof setTimeout> | undefined;
-  return function (...args: A) {
-    if (t !== undefined) {
-      clearTimeout(t);
-    }
-    t = setTimeout(() => {
-      t = undefined;
-      fn(...args);
-    }, wait);
-  };
+export interface Debounced<A extends unknown[]> {
+  (...args: A): void;
+  cancel(): void;
+}
+
+export function debounce<A extends unknown[]>(fn: (...args: A) => void, wait: number): Debounced<A> {
+  let timer: ReturnType<typeof setTimeout> | undefined;
+  const clear = () => {
+    if (timer !== undefined) {
+      clearTimeout(timer);
+      timer = undefined;
+    }
+  };
+  const debounced = ((...args: A) => {
+    clear();
+    timer = setTimeout(() => {
+      timer = undefined;
+      fn(...args);
+    }, wait);
+  }) as Debounced<A>;
+  debounced.cancel = clear;
+  return debounced;
 }
--- a/src/util/debounce.test.ts
+++ b/src/util/debounce.test.ts
@@ -12,3 +12,12 @@ test("collapses rapid calls", () => {
   vi.advanceTimersByTime(100);
   expect(fn).toHaveBeenCalledWith(3);
 });
+
+test("cancel drops the pending call", () => {
+  const fn = vi.fn();
+  const d = debounce(fn, 100);
+  d(1);
+  d.cancel();
+  vi.advanceTimersByTime(200);
+  expect(fn).not.toHaveBeenCalled();
+});

