Task: Add a groupBy(items, keyFn) utility that returns a Map from key to the items with that key.

Acceptance criteria:
- Returns a Map from each key to the array of items with that key
- Items within each group keep their original input order
- An empty input returns an empty result without throwing

Diff:
--- /dev/null
+++ b/src/util/groupBy.ts
@@ -0,0 +1,11 @@
+export function groupBy<T, K extends PropertyKey>(
+  items: readonly T[],
+  keyFn: (item: T) => K,
+): Record<K, T[]> {
+  const out = {} as Record<K, T[]>;
+  for (const item of items) {
+    const key = keyFn(item);
+    (out[key] ??= []).push(item);
+  }
+  return out;
+}
