Task: Make the generic TTL Cache safe for concurrent use from multiple goroutines.

Acceptance criteria:
- Set and Get can be called concurrently without data races (go test -race is clean)
- Get on a missing key returns the zero value and false
- Entries at or past their expiry time are treated as missing

Diff:
--- a/internal/cache/cache.go
+++ b/internal/cache/cache.go
@@ -1,31 +1,39 @@
 package cache

-import "time"
+import (
+	"sync"
+	"time"
+)

 type entry[V any] struct {
 	value     V
 	expiresAt time.Time
 }

 type Cache[K comparable, V any] struct {
+	mu    sync.RWMutex
 	items map[K]entry[V]
 	ttl   time.Duration
 	now   func() time.Time
 }

 func New[K comparable, V any](ttl time.Duration) *Cache[K, V] {
 	return &Cache[K, V]{items: make(map[K]entry[V]), ttl: ttl, now: time.Now}
 }

 func (c *Cache[K, V]) Set(key K, value V) {
+	c.mu.Lock()
+	defer c.mu.Unlock()
 	c.items[key] = entry[V]{value: value, expiresAt: c.now().Add(c.ttl)}
 }

 func (c *Cache[K, V]) Get(key K) (V, bool) {
+	c.mu.RLock()
 	e, ok := c.items[key]
+	c.mu.RUnlock()
 	if !ok || !c.now().Before(e.expiresAt) {
 		var zero V
 		return zero, false
 	}
 	return e.value, true
 }

