Task: Add textutil.Truncate(s, max) for shortening titles in notifications.

Acceptance criteria:
- Length is counted in runes, not bytes
- Truncated results end with "…" and are at most max runes long
- Strings already within max runes are returned unchanged
- max <= 0 returns the empty string

Diff:
--- /dev/null
+++ b/internal/textutil/truncate.go
@@ -0,0 +1,14 @@
+package textutil
+
+// Truncate shortens s to at most max runes, replacing the tail with an
+// ellipsis when anything was cut off.
+func Truncate(s string, max int) string {
+	if max <= 0 {
+		return ""
+	}
+	runes := []rune(s)
+	if len(runes) <= max {
+		return s
+	}
+	return string(runes[:max-1]) + "…"
+}
--- /dev/null
+++ b/internal/textutil/truncate_test.go
@@ -0,0 +1,22 @@
+package textutil
+
+import "testing"
+
+func TestTruncate(t *testing.T) {
+	cases := []struct {
+		in   string
+		max  int
+		want string
+	}{
+		{"hello", 10, "hello"},
+		{"hello", 5, "hello"},
+		{"hello world", 5, "hell…"},
+		{"héllo wörld", 3, "hé…"},
+		{"abc", 0, ""},
+	}
+	for _, c := range cases {
+		if got := Truncate(c.in, c.max); got != c.want {
+			t.Errorf("Truncate(%q, %d) = %q, want %q", c.in, c.max, got, c.want)
+		}
+	}
+}

