Task: Retry failed jobs in the queue worker instead of marking them failed immediately.

Acceptance criteria:
- When a job fails, it is re-enqueued (status "pending") until it has been retried maxRetries times
- maxRetries defaults to 3
- When the job fails after its last retry, its status becomes "dead"
- The number of attempts is persisted on the job

Diff:
--- a/src/queue/worker.ts
+++ b/src/queue/worker.ts
@@ -6,4 +6,5 @@ export interface Job {
   id: string;
   payload: unknown;
   status: "pending" | "running" | "done" | "failed" | "dead";
+  attempts?: number;
 }
@@ -13,14 +14,23 @@ export type Handler = (job: Job) => Promise<void>;
 export class Worker {
-  constructor(private queue: Queue, private handler: Handler) {}
+  constructor(
+    private queue: Queue,
+    private handler: Handler,
+    private maxRetries = 3,
+  ) {}

   async runOnce(): Promise<void> {
     const job = await this.queue.dequeue();
     if (!job) return;
     try {
       await this.handler(job);
       await this.queue.update(job.id, { status: "done" });
     } catch (err) {
-      await this.queue.update(job.id, { status: "failed" });
+      const attempts = (job.attempts ?? 0) + 1;
+      if (attempts <= this.maxRetries) {
+        await this.queue.update(job.id, { status: "pending", attempts });
+      } else {
+        await this.queue.update(job.id, { status: "dead", attempts });
+      }
     }
   }
 }

