+	in := []int64{3, 1, 3, 2, 1}
+	got := Dedupe(in)
+	if want := []int64{3, 1, 2}; !slices.Equal(got, want) {
+		t.Fatalf("Dedupe = %v, want %v", got, want)
+	}
