Task: Add IsBusinessDay(t) for UTC timestamps; weekends and the configured holiday dates are not business days.

Acceptance criteria:
- Saturdays and Sundays return false
- Any time of day on a listed holiday date returns false (timestamps are UTC)
- Other weekdays return true

Diff:
--- /dev/null
+++ b/internal/calendar/business.go
@@ -0,0 +1,22 @@
+package calendar
+
+import "time"
+
+var holidays = []time.Time{
+	time.Date(2025, time.December, 25, 0, 0, 0, 0, time.UTC),
+	time.Date(2026, time.January, 1, 0, 0, 0, 0, time.UTC),
+}
+
+// IsBusinessDay reports whether t falls on a weekday that is not a holiday.
+func IsBusinessDay(t time.Time) bool {
+	switch t.Weekday() {
+	case time.Saturday, time.Sunday:
+		return false
+	}
+	for _, h := range holidays {
+		if t.Equal(h) {
+			return false
+		}
+	}
+	return true
+}
