Task: Fix formatBytes so exact unit boundaries (e.g. 1024) roll over to the next unit instead of printing "1024 B".

Acceptance criteria:
- formatBytes(1024) returns "1.0 KB"
- Values below 1024 are shown as whole bytes, e.g. "512 B"
- formatBytes(1048576) returns "1.0 MB"
- Values of 1 GiB and above use GB with one decimal and never a larger unit

Diff:
--- a/src/format.ts
+++ b/src/format.ts
@@ -1,6 +1,12 @@
-export function formatBytes(n: number): string {
-  if (n > 1024 * 1024 * 1024) return (n / 1024 ** 3).toFixed(1) + " GB";
-  if (n > 1024 * 1024) return (n / 1024 ** 2).toFixed(1) + " MB";
-  if (n > 1024) return (n / 1024).toFixed(1) + " KB";
-  return n + " B";
-}
+const UNITS = ["KB", "MB", "GB"] as const;
+
+export function formatBytes(n: number): string {
+  if (n < 1024) return `${n} B`;
+  let value = n / 1024;
+  let unit = 0;
+  while (value >= 1024 && unit < UNITS.length - 1) {
+    value /= 1024;
+    unit++;
+  }
+  return `${value.toFixed(1)} ${UNITS[unit]}`;
+}
