Task: Write parseQuery(qs) to turn a URL query string into an object.

Acceptance criteria:
- A leading '?' is optional
- '+' is decoded as a space and percent-escapes are decoded
- Repeated keys are collected into an array in order of appearance
- A key without '=' maps to an empty string

Diff:
--- /dev/null
+++ b/src/url/parseQuery.ts
@@ -0,0 +1,14 @@
+export function parseQuery(qs: string): Record<string, string | string[]> {
+  const out: Record<string, string | string[]> = {};
+  const body = qs.startsWith("?") ? qs.slice(1) : qs;
+  if (!body) return out;
+  for (const part of body.split("&")) {
+    if (!part) continue;
+    const eq = part.indexOf("=");
+    const rawKey = eq === -1 ? part : part.slice(0, eq);
+    const rawValue = eq === -1 ? "" : part.slice(eq + 1);
+    const decode = (s: string) => decodeURIComponent(s.replace(/\+/g, " "));
+    out[decode(rawKey)] = decode(rawValue);
+  }
+  return out;
+}
--- /dev/null
+++ b/src/url/parseQuery.test.ts
@@ -0,0 +1,9 @@
+import { parseQuery } from "./parseQuery";
+
+test("decodes plus and percent escapes", () => {
+  expect(parseQuery("?q=hello+world&tag=a%26b")).toEqual({ q: "hello world", tag: "a&b" });
+});
+
+test("bare keys map to empty string", () => {
+  expect(parseQuery("debug&x=1")).toEqual({ debug: "", x: "1" });
+});

