Task: Replace the JWT library's built-in expiry check in verifyToken with our own so expired tokens raise AuthError; exp is the standard JWT claim in seconds since the epoch.

Acceptance criteria:
- Tokens without an exp claim are rejected with AuthError
- Tokens whose exp is at or before the current time are rejected with AuthError
- Tokens whose exp is in the future are accepted and their claims returned

Diff:
--- /dev/null
+++ b/src/auth/verify.ts
@@ -0,0 +1,19 @@
+import jwt from "jsonwebtoken";
+
+export class AuthError extends Error {}
+
+export interface Claims {
+  sub: string;
+  exp?: number;
+}
+
+export function verifyToken(token: string, secret: string): Claims {
+  const payload = jwt.verify(token, secret, { ignoreExpiration: true }) as Claims;
+  if (payload.exp === undefined) {
+    throw new AuthError("token has no exp claim");
+  }
+  if (payload.exp <= Date.now()) {
+    throw new AuthError("token expired");
+  }
+  return payload;
+}

