Task: Make getUserCity safe for partially loaded user records.

Acceptance criteria:
- Returns the user's city when present
- Returns "Unknown" when the user, the address or the city is null or undefined
- An empty-string city also returns "Unknown"

Diff:
--- a/src/users/format.ts
+++ b/src/users/format.ts
@@ -1,5 +1,5 @@
 import type { User } from "./types";

-export function getUserCity(user: User): string {
-  return user.address.city;
+export function getUserCity(user: User | null | undefined): string {
+  return user?.address?.city || "Unknown";
 }
--- /dev/null
+++ b/src/users/format.test.ts
@@ -0,0 +1,12 @@
+import { getUserCity } from "./format";
+import type { User } from "./types";
+
+const withCity = (city: string | undefined) => ({ id: "u1", address: { city } }) as unknown as User;
+
+test("returns the city", () => expect(getUserCity(withCity("Oslo"))).toBe("Oslo"));
+test("missing pieces fall back to Unknown", () => {
+  expect(getUserCity(null)).toBe("Unknown");
+  expect(getUserCity({ id: "u1" } as unknown as User)).toBe("Unknown");
+  expect(getUserCity(withCity(undefined))).toBe("Unknown");
+});
+test("empty city is treated as missing", () => expect(getUserCity(withCity(""))).toBe("Unknown"));

