Task: Send a Content-Security-Policy header on every response from the Express app.

Acceptance criteria:
- Every response carries a Content-Security-Policy header
- The policy includes default-src 'self'
- The policy includes frame-ancestors 'none'

Diff:
--- /dev/null
+++ b/src/middleware/securityHeaders.ts
@@ -0,0 +1,8 @@
+import type { NextFunction, Request, Response } from "express";
+
+const CSP = ["default-src 'self'", "frame-ancestors 'none'"].join("; ");
+
+export function securityHeaders(_req: Request, res: Response, next: NextFunction): void {
+  res.setHeader("Content-Security-Policy", CSP);
+  next();
+}
--- a/src/app.ts
+++ b/src/app.ts
@@ -1,6 +1,8 @@
 import express from "express";
 import { apiRouter } from "./routes";
+import { securityHeaders } from "./middleware/securityHeaders";

 const app = express();
+app.use(securityHeaders);
 app.use(express.json());
 app.use("/api", apiRouter);

