+package stats
+
+import "errors"
+
+var ErrEmpty = errors.New("stats: no values")
+
+// Average returns the arithmetic mean of xs.
+func Average(xs []float64) (float64, error) {
+	if len(xs) == 0 {
+		return 0, ErrEmpty
+	}
+	var sum float64
+	for _, x := range xs {
+		sum += x
+	}
+	return sum / float64(len(xs)), nil
+}
--- /dev/null
+++ b/internal/stats/average_test.go
@@ -0,0 +1,15 @@
+package stats
+
+import (
+	"errors"
+	"testing"
+)
+
+func TestAverage(t *testing.T) {
+	if got, _ := Average([]float64{1, 2, 3, 4}); got != 2.5 {
+		t.Errorf("Average = %v, want 2.5", got)
+	}
+	if _, err := Average(nil); !errors.Is(err, ErrEmpty) {
+		t.Errorf("want ErrEmpty, got %v", err)
+	}
+}

