Task: Add a CartStore with addItem(productId, qty) that UI components can subscribe to for changes.

Acceptance criteria:
- Adding a product already in the cart increments its quantity
- A qty that is not a positive integer throws RangeError
- A "change" event is emitted after every successful addItem

Diff:
--- /dev/null
+++ b/src/cart/cartStore.ts
@@ -0,0 +1,16 @@
+import { EventEmitter } from "node:events";
+
+export class CartStore extends EventEmitter {
+  private items = new Map<string, number>();
+
+  addItem(productId: string, qty = 1): void {
+    if (!Number.isInteger(qty) || qty <= 0) {
+      throw new RangeError(`qty must be a positive integer, got ${qty}`);
+    }
+    this.items.set(productId, (this.items.get(productId) ?? 0) + qty);
+  }
+
+  quantityOf(productId: string): number {
+    return this.items.get(productId) ?? 0;
+  }
+}
--- /dev/null
+++ b/src/cart/cartStore.test.ts
@@ -0,0 +1,14 @@
+import { CartStore } from "./cartStore";
+
+test("adding the same product twice increments quantity", () => {
+  const cart = new CartStore();
+  cart.addItem("sku-1", 2);
+  cart.addItem("sku-1");
+  expect(cart.quantityOf("sku-1")).toBe(3);
+});
+
+test("rejects invalid quantities", () => {
+  const cart = new CartStore();
+  expect(() => cart.addItem("sku-1", 0)).toThrow(RangeError);
+  expect(() => cart.addItem("sku-1", 1.5)).toThrow(RangeError);
+});

