Task: Read database settings from the environment instead of hard-coding them.

Acceptance criteria:
- The pool connects using DATABASE_URL
- Importing the module throws if DATABASE_URL is unset or empty
- Pool size comes from DB_POOL_SIZE, defaulting to 10 when unset

Diff:
--- a/src/db.ts
+++ b/src/db.ts
@@ -1,3 +1,14 @@
 import { Pool } from "pg";

-export const pool = new Pool({ connectionString: "postgres://localhost/app", max: 5 });
+function requireEnv(name: string): string {
+  const value = process.env[name];
+  if (!value) {
+    throw new Error(`Missing required environment variable ${name}`);
+  }
+  return value;
+}
+
+export const pool = new Pool({
+  connectionString: requireEnv("DATABASE_URL"),
+  max: Number(process.env.DB_POOL_SIZE ?? 10),
+});

